import csv,hashlib,json
from pathlib import Path
p=Path(__file__).resolve().parent;root=p.parents[1];atlas=root/'locus_atlas/brain6_six_region_atlas.tsv';context=root/'variant_context/selected_variant_gene_context.tsv'
def read(f):
 with f.open() as h:return list(csv.DictReader(h,delimiter='\t'))
a=read(atlas);c=read(context);assert len(a)==6
lines=['# Regional AlphaGenome peaks versus shared genetic evidence','','These are the largest absolute predicted adult frontal-cortex DNase changes among the already selected variants **within each region**. The prediction is ALT versus REF over a 501-base window with offset 1; it is not a measured effect, gene-level expression, disease-risk direction, p-value or calibrated causal probability. The region-level PP4 is a single-signal trait–trait colocalization posterior, not a posterior for the named peak variant.','', '| Region (GRCh37) | Peak variant (GRCh38) | Predicted change | In insomnia / ADHD selected sets? | Regional PP4 at p12=10⁻⁵ / 10⁻⁶ | Positional gene context |','|---|---|---:|---|---:|---|']
for row in a:
 rs=row['max_abs_adult_dnase_snp']; matches=[z for z in c if z['region']==row['candidate_locus_id'] and z['snp']==rs and 'max_abs_adult_dnase' in z['selection_reasons']];assert len(matches)==1;x=matches[0];assert x['grch38_ref_alt']==row['max_abs_adult_dnase_grch38_ref_alt'];assert abs(float(x['adult_dnase_log2ratio'])-float(row['max_abs_adult_dnase_adult_dnase_log2ratio']))<1e-12
 overlap=x['overlapping_genes'];near=x['nearest_gene'];dist=x['nearest_gene_distance_bp'];gene=('Overlaps '+', '.join(z.split('|')[0] for z in overlap.split(';'))) if overlap else ('Nearest '+near+' ('+dist+' bp)' if near else 'No annotated gene returned')
 fmt=lambda v:'yes' if v=='YES' else 'no'
 lines.append(f"| {row['region_grch37']} | {rs}; {x['grch38_ref_alt']} | {float(x['adult_dnase_log2ratio']):+.3f} | {fmt(x['insomnia_credible_set_member'])} / {fmt(x['adhd_credible_set_member'])} | {float(row['ABF_coloc_PP4_p12_1e-5']):.3g} / {float(row['ABF_coloc_PP4_p12_1e-6']):.3g} | {gene} |")
lines+=['','**Interpretation.** rs62264764 has the largest absolute prediction across the selected 425 variants and is in both admitted sets, but its regional PP4 falls under the lower sharing prior; neither establishes LSAMP or LINC03051 as the effector gene. The chr5:103 Mb region has the highest PP4 of these regions under both tested priors, but its peak-prediction variant rs2447828 is not in the admitted ADHD set; region-level sharing cannot be transferred to that particular marker. The chr11 and chr5:87 Mb regional models provide little H4 support at these priors despite having a predicted peak. A “no” means the variant is outside the project’s selected, admitted credible set, not that it has no association or cannot be causal.','', 'Genes are overlap or nearest-gene annotations from the recorded Ensembl queries, not experimentally validated targets; numeric gene identifiers are kept when no gene symbol was returned. Gene boundaries, selected sets and 1-Mb windows are model- and release-dependent. No independent two-trait locus replication was verified, the original LAVA gates failed, and all entries are hypotheses for follow-up. Cross-variant prediction ranking is sensitive to window and offset choices; the JBrowse model release was not exposed.','', 'Sources: [six-region locus atlas](../LOCUS_ATLAS.md), [prediction ranking](../../prediction_rank_comparison/REPORT.md), [window sensitivity](../../alphagenome_window_sensitivity/RESULTS.md), and [LSAMP evidence review](../../variant_context/rs62264764_lsamp_prior/RESULTS.md). [Code](build.py) and [input receipt](receipt.json) reproduce this selected-view table. The user-authorized AlphaGenome outputs are used for non-commercial research, not model training.']
(p/'RESULTS.md').write_text('\n'.join(lines)+'\n');(p/'receipt.json').write_text(json.dumps({'input_sha256':{str(x.relative_to(root)):hashlib.sha256(x.read_bytes()).hexdigest() for x in [atlas,context]},'regions':len(a),'matched_peak_annotations':6,'scope':'descriptive view of selected variants; no new association or predictions'},indent=2)+'\n');print('verified six region peak joins')
